function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
  const [x, y] = cell;
  const [candidateX, candidateY] = candidate;
  const isTouching =
    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
  return isTouching && !isSameCell(cell, candidate);
}

function countLivingNeighbours(cell: Cell, livingCells: Cell[]): number {
  return livingCells.filter((candidate) => isNeighbourOf(cell, candidate))
    .length;
}

function survives(cell: Cell, livingCells: Cell[]): boolean {
  const livingNeighbours = countLivingNeighbours(cell, livingCells);
  return livingNeighbours === 2 || livingNeighbours === 3;
}

export function nextGeneration(livingCells: Cell[]): Cell[] {
  return livingCells.filter((cell) => survives(cell, livingCells));
}
